/bin/bash -lc "python3 - <<'PY'
import ast,json,hashlib
from pathlib import Path
root=Path('/workspace');p=json.loads((root/'proposal.json').read_text());r=json.load(open('/tmp/runtime_resolved.json'))
# Validate the actual supplied study schema with standard library only.
def validate(x,s,path):
 t=s.get('type');ok={'object':lambda:isinstance(x,dict),'array':lambda:isinstance(x,list),'string':lambda:isinstance(x,str)}
 if t:assert ok[t](),(path,t)
 if 'const' in s:assert x==s['const'],path
 if 'enum' in s:assert x in s['enum'],path
 if 'minLength' in s:assert len(x)>=s['minLength'],path
 if 'minItems' in s:assert len(x)>=s['minItems'],path
 if isinstance(x,dict):
  assert all(k in x for k in s.get('required',[])),path
  if s.get('additionalProperties') is False:assert set(x)<=set(s.get('properties',{})),path
  for k,v in x.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
 if isinstance(x,list) and 'items' in s:
  for i,v in enumerate(x):validate(v,s['items'],path+f'[{i}]')
validate(p['study'],r['study_schema'],'study')
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
ancestor=ast.parse((root/'history_g0_r0028_dispatch_folded.py').read_text())
old_class=next(n for n in ancestor.body if isinstance(n,ast.ClassDef) and n.name=='Model')
old_methods={n.name:ast.dump(n,include_attributes=False) for n in old_class.body if isinstance(n,ast.FunctionDef)}
canonical=[]
for v in p['variants']:
 assert set(v)=={'name','file','role','config','note'}
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 assert v['role'] in ['candidate','control']
 src=(root/v['file']).read_text();tree=ast.parse(src);compile(tree,v['file'],'exec') # never executes
 cfg=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 assert cfg==v['config']
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 assert set(methods)==set(old_methods)
 for name,node in methods.items():
  if name not in ['__init__','forward','_auxiliary_activation']:assert ast.dump(node,include_attributes=False)==old_methods[name],(v['name'],name)
 init=methods['__init__'];defaults={a.arg:ast.literal_eval(d) for a,d in zip(init.args.args[-len(init.args.defaults):],init.args.defaults)}
 for k,val in cfg.items():
  default=defaults[k]
  if isinstance(default,tuple):default=list(default)
  assert default==val,(v['name'],k,default,val)
 for n in ast.walk(tree):
  if isinstance(n,ast.Import):assert all(a.name.split('.')[0] in {'torch','unirank'} for a in n.names)
  if isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in {'torch','unirank'}
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','eval','exec','compile','__import__','input'}
 # Only the two population CONFIG/default constants may vary across cells.
 for n in tree.body:
  if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets):n.value=ast.Constant(value='CONFIG-normalized')
 for i,arg in enumerate(init.args.args[-len(init.args.defaults):]):
  if arg.arg in ['auxiliary_train_population','auxiliary_eval_population']:init.args.defaults[i]=ast.Constant(value='population-normalized')
 canonical.append(ast.dump(tree,include_attributes=False))
 print(v['name'],'syntax/schema/config/import checks passed; sha256='+hashlib.sha256(src.encode()).hexdigest())
assert len(set(canonical))==1
print('Study schema and authorized evidence/protocol checks passed; factorial modules have identical executable AST except population flags. All inherited helpers unchanged.')
PY"

